import {setupBlackholeControls} from './blackhole-controls.js';
import {capture4K,graphicsQuality} from './graphics.js';
import * as T from './assets/three.module.js';
import {blackholeFragment} from './blackhole-shader.js';
import {blackholeReference} from './blackhole-math.js';
import {setupRelativityLab} from './relativity-lab.js';
const $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const compact=n=>n>=1e9?(n/1e9).toFixed(2)+' billion':n>=1e6?(n/1e6).toFixed(2)+' million':n.toLocaleString('en-US',{maximumFractionDigits:1});
export function setupSingularity(api){
 const section=document.createElement('section');section.id='singularity';section.className='horizon-section';
 section.innerHTML=`
 <div class="horizon-hero">
   <div id="singularity-render" tabindex="0" role="img" aria-label="Interactive black hole. Drag to orbit, pinch to zoom. Arrow keys rotate, plus and minus zoom, zero resets."></div>
   <div class="horizon-vignette"></div>
   <div class="horizon-topline"><span><i></i> ORBIT / EXTREME UNIVERSE</span><span>CHAPTER 01 — THE INVISIBLE</span></div>
   <div class="horizon-copy"><span class="horizon-kicker">AT THE EDGE OF UNDERSTANDING</span><h1>BEYOND<br>THE<br><em>VISIBLE.</em></h1><p>Light bends. Time stretches.<br>Nothing here behaves quite like home.</p><div class="horizon-actions"><a class="primary" href="#relativity-lab">Enter the experiments <span>↗</span></a><button id="bh-tour">Follow the light <span>→</span></button></div><div class="horizon-story"><span id="bh-chapter">01 / THE SHADOW</span><h2 id="bh-story-title">An absence that reveals everything.</h2><p id="bh-story-copy">The dark silhouette is larger than the event horizon. Light that would have reached your eye has been captured.</p></div></div>
   <div class="horizon-label" id="bh-annotation"><span>PHOTON RING</span><i></i><small>LIGHT TAKING THE LONG WAY HOME</small></div>
   <div class="horizon-camera"><button data-bh-camera="cinematic" aria-pressed="true">01 <span>Cinematic</span></button><button data-bh-camera="polar" aria-pressed="false">02 <span>Polar</span></button><button data-bh-camera="edge" aria-pressed="false">03 <span>Edge-on</span></button><span>DRAG TO ORBIT / + − TO ZOOM</span></div>
   <div class="horizon-utility"><button id="blackhole-pause" aria-pressed="false" aria-label="Pause black hole animation">Ⅱ</button><button id="bh-capture" aria-label="Save black hole image">↧</button><button id="bh-fullscreen" aria-label="Enter black hole fullscreen">⛶</button></div>
   <div class="horizon-bottom"><span id="bh-render-status">LOCAL RAY INTEGRATION / SCHWARZSCHILD REFERENCE</span><a href="#relativity-lab">KEEP EXPLORING <span>↓</span></a><span>INDEPENDENT OBSERVATORY / 2026</span></div>
 </div>
 <div class="horizon-instruments wrap">
   <div class="bh-presets"><span class="eyebrow">CHOOSE A SCALE</span><button data-bh-mass="10" aria-pressed="true"><span>01 / STELLAR</span><strong>Stellar remnant</strong><small>10 solar masses</small></button><button data-bh-mass="4300000" aria-pressed="false"><span>02 / GALACTIC CENTER</span><strong>Sagittarius A*</strong><small>≈ 4.3 million solar masses</small></button><button data-bh-mass="6500000000" aria-pressed="false"><span>03 / SUPER MASSIVE</span><strong>M87*</strong><small>≈ 6.5 billion solar masses</small></button></div>
   <div class="bh-console"><label>Mass / logarithmic scale <output id="bh-mass-label">10 M☉</output><input id="blackhole-mass" type="range" min="0" max="10" step=".01" value="1"></label><div class="bh-switches" role="group" aria-label="Black hole rendering controls"><button id="bh-lensing" aria-pressed="true">Lensing</button><button id="bh-disk" aria-pressed="true">Accretion disk</button><button id="bh-grid" aria-pressed="false">Lensing grid</button><button id="bh-jets" aria-pressed="false">Polar jets</button><button id="blackhole-pulse">Inject matter ↗</button><button id="blackhole-reset">Reset view ↺</button></div><label>Exposure<input id="blackhole-exposure" type="range" min=".3" max="2.5" step=".05" value="1.2"></label><label>Flow / visual speed<input id="blackhole-flow" type="range" min=".2" max="3" step=".1" value="1"></label><label>Render quality<select id="bh-quality"><option value="balanced">Balanced</option><option value="high">Ultra detail</option><option value="4k">4K / 3840 cap</option><option value="low">Efficient</option></select></label></div>
   <div id="blackhole-readout" class="bh-readout" aria-live="polite"></div>
   <p class="bh-model-note">A normalized optical experiment: changing mass changes the physical scale, not the silhouette in horizon units. Bent rays sample a synthetic disk; emission, polar jets and the thin ring glow are illustrative. Nonrotating reference; no Kerr spin or measured telescope image. <a href="https://www.nasa.gov/universe/nasa-visualization-shows-a-black-holes-warped-world/" target="_blank" rel="noopener">Read the NASA explanation ↗</a></p>
 </div>
 <div class="relativity-lab wrap" id="relativity-lab"></div>
 <div class="experience-index wrap"><div><span class="eyebrow">A UNIVERSE OF POSSIBILITIES</span><h2>Curiosity has<br>no final frontier.</h2></div><a href="#explore"><span>01 / WORLDS</span><strong>Find your<br>perspective.</strong><small>Eight worlds, from orbit to terrain. ↗</small><i class="index-planet"></i></a><a href="#gravity-studio"><span>02 / DYNAMICS</span><strong>Put gravity<br>to the test.</strong><small>One drop. Three different worlds. ↗</small><i class="index-gravity"></i></a><a href="#light-lab"><span>03 / CONNECTIONS</span><strong>Send something<br>into the dark.</strong><small>Signals, fields, and the speed of light. ↗</small><i class="index-signal"></i></a></div>`;
 const placeholder=document.querySelector('#singularity');if(placeholder)placeholder.replaceWith(section);else document.querySelector('main').prepend(section);
 let mass=10,yaw=.28,pitch=.20,distance=19,goalYaw=yaw,goalPitch=pitch,goalDistance=distance;
 let paused=false,visible=false,failed=false,time=0,last=0,pulse=0,capture=false,dirty=true,renderer,scene,camera,chapter=0;
 const root=$('#singularity-render'), uniform={resolution:{value:new T.Vector2(1,1)},time:{value:0},yaw:{value:yaw},pitch:{value:pitch},distance:{value:distance},center:{value:.64},lensing:{value:1},diskOn:{value:1},gridOn:{value:0},exposure:{value:1.2},activity:{value:1},jets:{value:0},pulse:{value:0},quality:{value:259}};
 const advanced=setupBlackholeControls(section,uniform,{preset,dirty:()=>dirty=true});
 function size(){if(!renderer)return;const r=root.getBoundingClientRect(),q=$('#bh-quality').value,cap=q==='4k'?3840:q==='high'?2560:q==='low'?900:1500,scale=Math.min(q==='4k'?3840/r.width:devicePixelRatio||1,cap/r.width,(q==='4k'?2160:1600)/r.height);renderer.setSize(Math.max(1,r.width*scale),Math.max(1,r.height*scale),false);renderer.domElement.style.width='100%';renderer.domElement.style.height='100%';uniform.resolution.value.set(renderer.domElement.width,renderer.domElement.height);uniform.center.value=r.width<760?.5:.64;uniform.quality.value=q==='low'?179:q==='balanced'?279:359;dirty=true;}
 try {
   if(new URLSearchParams(location.search).get('graphics')==='basic')throw new Error('Basic graphics');
   renderer=new T.WebGLRenderer({antialias:false,powerPreference:'high-performance',preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.debug.onShaderError=()=>fallback('Optical shader unavailable. The numerical experiments remain ready below.');root.append(renderer.domElement);
   scene=new T.Scene();camera=new T.OrthographicCamera(-1,1,1,-1,0,1);const material=new T.ShaderMaterial({uniforms:uniform,vertexShader:'void main(){gl_Position=vec4(position.xy,0.,1.);}',fragmentShader:blackholeFragment});scene.add(new T.Mesh(new T.PlaneGeometry(2,2),material));new ResizeObserver(size).observe(root);size();
   renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();fallback('Graphics context lost. Reload or continue with the numerical experiments.');});
 } catch(e){fallback('Basic graphics / numerical experiments are ready below.');}
 function fallback(message){failed=true;root.classList.add('bh-fallback');root.innerHTML='<div class="fallback-hole" aria-hidden="true"></div>';$('#bh-render-status').textContent=message;$('#bh-capture').disabled=true;}
 function readout(){const r=blackholeReference(mass);$('#bh-mass-label').textContent=compact(mass)+' M☉';$('#blackhole-readout').innerHTML=[['EVENT HORIZON',compact(r.rs)+' km'],['PHOTON SPHERE',compact(r.photonSphere)+' km'],['INNER STABLE ORBIT',compact(r.isco)+' km'],['DIAMETER LIGHT TIME',r.crossingSeconds<1?(r.crossingSeconds*1000).toFixed(3)+' ms':compact(r.crossingSeconds)+' s']].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('');section.querySelectorAll('[data-bh-mass]').forEach(b=>b.setAttribute('aria-pressed',Math.abs(+b.dataset.bhMass-mass)<mass*.001));document.dispatchEvent(new CustomEvent('blackhole-mass',{detail:{mass}}));}
 $('#blackhole-mass').oninput=e=>{mass=10**+e.target.value;readout()};section.querySelectorAll('[data-bh-mass]').forEach(b=>b.onclick=()=>{mass=+b.dataset.bhMass;$('#blackhole-mass').value=Math.log10(mass);readout()});
 for(const [id,key] of [['bh-lensing','lensing'],['bh-disk','diskOn'],['bh-grid','gridOn'],['bh-jets','jets']])$('#'+id).onclick=e=>{uniform[key].value=1-uniform[key].value;e.currentTarget.setAttribute('aria-pressed',!!uniform[key].value);dirty=true;};
 for(const [id,key] of [['blackhole-exposure','exposure'],['blackhole-flow','activity']])$('#'+id).oninput=e=>{uniform[key].value=+e.target.value;dirty=true;};
 $('#bh-quality').onchange=size;document.addEventListener('graphics-quality',()=>{$('#bh-quality').value=({auto:'balanced',efficient:'low',ultra:'high','4k':'4k'})[graphicsQuality()];size()});
 $('#blackhole-pause').onclick=e=>{paused=!paused;e.currentTarget.setAttribute('aria-pressed',paused);e.currentTarget.textContent=paused?'▶':'Ⅱ';e.currentTarget.setAttribute('aria-label',paused?'Resume black hole animation':'Pause black hole animation');};
 $('#blackhole-pulse').onclick=()=>{pulse=1;dirty=true;$('#bh-render-status').textContent='MATTER INJECTION / ILLUSTRATIVE LUMINOSITY BURST';};
 function preset(name){[goalYaw,goalPitch,goalDistance]=name==='photon'?[.2,.08,11]:name==='polar'?[.1,1.45,23]:name==='edge'?[.3,.025,19]:[.28,.20,19];section.querySelectorAll('[data-bh-camera]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.bhCamera===name));dirty=true;}
 section.querySelectorAll('[data-bh-camera]').forEach(b=>b.onclick=()=>preset(b.dataset.bhCamera));$('#blackhole-reset').onclick=()=>preset('cinematic');
 const stories=[['THE SHADOW','An absence that reveals everything.','The dark silhouette is larger than the event horizon. Light that would have reached your eye has been captured.','PHOTON RING','LIGHT TAKING THE LONG WAY HOME'],['THE LENS','The far side comes into view.','Gravity bends light from behind the disk over and under the shadow. Toggle lensing to see the difference.','THE FAR SIDE','BENT INTO VIEW BY GRAVITY'],['THE DISK','Matter gives darkness an outline.','The disk is hot orbiting material outside the horizon. One side appears brighter as it moves toward your line of sight.','ACCRETION DISK','MATTER IN ORBIT, OUTSIDE THE HORIZON'],['YOUR EXPERIMENT','Now change the rules.','Send a photon past the edge. Compare two clocks. Discover why a bigger black hole can have gentler tides at its horizon.','YOUR NEXT DISCOVERY','THREE EXPERIMENTS BELOW']];
 $('#bh-tour').onclick=()=>{chapter=(chapter+1)%stories.length;const s=stories[chapter];$('#bh-chapter').textContent=`0${chapter+1} / ${s[0]}`;$('#bh-story-title').textContent=s[1];$('#bh-story-copy').textContent=s[2];$('#bh-annotation').innerHTML=`<span>${s[3]}</span><i></i><small>${s[4]}</small>`;preset(chapter===2?'polar':'cinematic');$('#bh-tour').innerHTML=chapter===3?'Back to the shadow ↺':'Next chapter <span>→</span>';};
 const pointers=new Map();let previous={x:0,y:0},pinch=0;
 root.addEventListener('pointerdown',e=>{root.focus({preventScroll:true});root.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});previous={x:e.clientX,y:e.clientY};if(pointers.size===2){const a=[...pointers.values()];pinch=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}});
 root.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);goalDistance=clamp(goalDistance*Math.exp((pinch-d)*.005),11,32);pinch=d;}else{goalYaw-=(e.clientX-previous.x)*.006;goalPitch=clamp(goalPitch+(e.clientY-previous.y)*.005,-1.45,1.45);}previous={x:e.clientX,y:e.clientY};dirty=true;section.querySelectorAll('[data-bh-camera]').forEach(b=>b.setAttribute('aria-pressed',false));});
 ['pointerup','pointercancel','lostpointercapture'].forEach(type=>root.addEventListener(type,e=>{pointers.delete(e.pointerId);if(pointers.size)previous=[...pointers.values()][0];}));
 root.addEventListener('wheel',e=>{if(document.activeElement!==root&&!e.ctrlKey)return;e.preventDefault();goalDistance=clamp(goalDistance*Math.exp(e.deltaY*.001),11,32);dirty=true;},{passive:false});
 root.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','0'].includes(e.key))return;e.preventDefault();if(e.key==='0')preset('cinematic');if(e.key==='ArrowLeft')goalYaw-=.12;if(e.key==='ArrowRight')goalYaw+=.12;if(e.key==='ArrowUp')goalPitch=clamp(goalPitch+.08,-1.45,1.45);if(e.key==='ArrowDown')goalPitch=clamp(goalPitch-.08,-1.45,1.45);if(e.key==='+'||e.key==='=')goalDistance=clamp(goalDistance-1,11,32);if(e.key==='-')goalDistance=clamp(goalDistance+1,11,32);dirty=true;});
 $('#bh-capture').onclick=()=>{capture=true;dirty=true;};$('#bh-fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await section.querySelector('.horizon-hero').requestFullscreen();}catch(e){$('#bh-render-status').textContent='FULLSCREEN UNAVAILABLE IN THIS BROWSER';}};
 new IntersectionObserver(e=>{visible=e[0].isIntersecting;if(visible){dirty=true;document.querySelectorAll('.header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#singularity'));}}).observe(root);
 new IntersectionObserver(e=>{if(e[0].isIntersecting)document.querySelectorAll('.header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#relativity-lab'));},{rootMargin:'-15% 0px -55% 0px'}).observe($('#relativity-lab'));
 function frame(now){requestAnimationFrame(frame);const dt=Math.min(.06,(now-last)/1000)||0;last=now;if(!visible||document.hidden||failed)return;const moving=api.getState().motion&&!paused;
   const change=Math.abs(yaw-goalYaw)+Math.abs(pitch-goalPitch)+Math.abs(distance-goalDistance);if(!moving&&!dirty&&change<.001)return;
   advanced.frame(dt,moving);if(moving){time+=dt;pulse=Math.max(0,pulse-dt*.3);}const damp=api.getState().motion?1-Math.exp(-dt*8):1;yaw+=(goalYaw-yaw)*damp;pitch+=(goalPitch-pitch)*damp;distance+=(goalDistance-distance)*damp;
   uniform.time.value=time;uniform.yaw.value=yaw;uniform.pitch.value=pitch;uniform.distance.value=distance;uniform.pulse.value=pulse;renderer.render(scene,camera);dirty=false;
   if(capture){capture=false;const oldCenter=uniform.center.value,oldQuality=uniform.quality.value;capture4K(renderer,scene,camera,'ORBIT-Event-Horizon-4K.png',()=>{uniform.resolution.value.set(3840,2160);uniform.center.value=.5;uniform.quality.value=359;renderer.render(scene,camera)});uniform.center.value=oldCenter;uniform.quality.value=oldQuality;size();}
 }
 setupRelativityLab(api,()=>mass);readout();requestAnimationFrame(frame);
 if(location.hash==='#singularity'||location.hash==='#relativity-lab')document.querySelector(location.hash)?.scrollIntoView();
}
